// Generated by scripts/build_data.py from data/experiments.json and data/chips.json — do not edit by hand.
export const EXPERIMENTS = {"schema_version":1,"intro":{"title":"Experiments you can run","lead":"Fourteen experiments that make the physics of chip making measurable, from sand on a paper wafer to a diode thermometer. Each one turns your readings into a straight line, fits it here in the browser, and sets the result beside the cited value."},"tiers":[{"tier":0,"name":"Tier 0 · anywhere","text":"Paper, a pencil, kitchen things or a spreadsheet. Nothing hot, sharp or powered beyond a multimeter’s own battery."},{"tier":1,"name":"Tier 1 · home or classroom, with care","text":"Low-voltage electronics from batteries or a USB supply, a labelled Class 2 laser pointer, warm water or sunlight. An adult should help with anything hot."},{"tier":2,"name":"Tier 2 · teaching lab","text":"Equipment that belongs in a supervised teaching lab, such as a four-point probe station. Done there, under that lab’s rules."},{"tier":3,"name":"Tier 3 · institution only","text":"Hazardous chemistry, furnaces or gases. Explained here conceptually only: no recipes, concentrations or temperatures are published."}],"experiments":[{"id":"yield","n":1,"tier":0,"model":"yield_poisson","time":"30 minutes","title":"Sprinkle sand on a wafer and count the good dies","short":"Defects and yield: why big chips cost more","question":"If dust lands at random, what fraction of chips escapes it, and how does that depend on chip size?","analog":"A particle that lands on a die usually kills it. Each grain you drop is a particle; each square of the grid is a die.","links":[{"label":"Cleaning theatre","href":"fab.html#proc-cleaning"},{"label":"Yield and cost lab","href":"process.html#yield"},{"label":"Manual 2: cleaning","href":"manuals/cleaning.html"}],"need":["A large circle drawn on paper as the wafer","Grids of squares of four sizes drawn inside four copies of the circle","A small handful of rice, lentils or dry sand","A ruler"],"steps":["Draw four identical circles. Fill each with a grid of squares of one size, for example 1, 2, 3 and 4 cm across.","Count the whole squares inside each circle. Ignore partial squares at the edge, as fabs do.","Hold the same number of grains well above each circle and let them fall. Spread them gently if they clump.","Count the squares with no grain in them. Yield is that count divided by the whole squares.","Write one row per grid: the area of one square in cm², and the yield as a fraction."],"measure":"area in cm², yield as a fraction from 0 to 1","cols":[{"id":"area","label":"Die area","unit":"cm²"},{"id":"yield","label":"Yield","unit":"fraction"}],"params":[],"results":[{"key":"D","label":"Defect density D","unit":"per cm²","digits":3}],"compare":[{"text":"With random defects, yield falls as Y = exp(−D·A): double the die area and you square the yield. This is the Poisson yield model.","refs":["murphy1964"]},{"text":"Real defects cluster, so fabs use the negative-binomial model, which loses fewer large dies than Poisson predicts.","refs":["stapper1973","stapper1983"]}],"leaves_out":["Grains bounce and clump; real particles stick where they land.","Not every particle kills a die: only those larger than a critical size, in a sensitive spot.","Clustering, which the negative-binomial model adds."],"refs":["murphy1964","stapper1973","stapper1983"],"example":{"xs":[1,4,9,16],"truth":{"D":0.08},"noise":0.04,"seed":11,"note":"Made with D = 0.08 per cm², an example value."}},{"id":"moore","n":2,"tier":0,"model":"moore","time":"20 minutes","title":"Measure Moore’s law yourself","short":"Fit the doubling time from real chips","question":"How many years does it take for the number of transistors on a chip to double?","analog":"Every chip in the site’s chip list is a data point. Taking log₂ of the count turns exponential growth into a straight line.","links":[{"label":"Moore’s law chart","href":"index.html#moore"},{"label":"Chips","href":"index.html#chips"}],"need":["Nothing: the real data is built in","A spreadsheet if you want to add chips of your own"],"steps":["Press “Use real data” to load every production chip from the site’s chip list: year and transistor count.","The fit plots log₂(count) against year. The slope is doublings per year.","Delete the oldest or newest rows and refit. Does the doubling time change with the era you choose?"],"measure":"year, transistor count","cols":[{"id":"year","label":"Year","unit":""},{"id":"transistors","label":"Transistors","unit":"count"}],"params":[],"results":[{"key":"T_years","label":"Doubling time","unit":"years","digits":2}],"compare":[{"text":"Moore first projected a doubling every year (1965), then revised it to every two years (1975).","refs":["moore1965","moore1975"]}],"leaves_out":["The list favours famous chips, not a random sample.","Transistor count says nothing about cost per transistor, which is what Moore’s argument was about."],"refs":["moore1965","moore1975"],"real":{"source":"chips","note":"Production chips from data/chips.json (the same set as the Moore’s law chart)."},"example":null},{"id":"gelatin","n":3,"tier":1,"model":"sqrt_t","time":"1 day","title":"Watch dye diffuse into gelatin","short":"Why diffusion depth grows as the square root of time","question":"Dopants spread into silicon by diffusion. Does the front move steadily, or does it slow down?","analog":"Gelatin plays the silicon and food colouring plays the dopant. A drop on the surface is a constant surface source, like a predeposition.","links":[{"label":"Diffusion theatre","href":"fab.html#proc-diffusion"},{"label":"Manual 6A: diffusion","href":"manuals/diffusion.html"}],"need":["Unflavoured gelatin set in a clear straight-sided glass (an adult makes it with hot water)","Food colouring","A ruler with millimetres","A clock"],"steps":["Let the gelatin set fully and come to room temperature.","Cover the top with a thin layer of coloured water. Start the clock.","At growing intervals, measure how far below the surface the colour reaches. Use the same judgement of “coloured” each time.","Write one row per reading: time in minutes and depth in millimetres."],"measure":"time in minutes, front depth in millimetres","cols":[{"id":"t_min","label":"Time","unit":"min"},{"id":"x_mm","label":"Depth","unit":"mm"}],"params":[],"results":[{"key":"k_mm2_per_min","label":"Slope of depth² against time","unit":"mm²/min","digits":3},{"key":"t0_min","label":"Time offset","unit":"min","digits":1}],"compare":[{"text":"From a constant surface source, any fixed concentration sits at a depth x = 2√(Dt)·erfc⁻¹(C/C_s). Depth squared therefore grows in proportion to time, just as for dopants in silicon.","refs":["plummer2000"]}],"leaves_out":["The slope is 4D times a factor set by where you judge the colour ends, so it gives D only up to that factor.","Gelatin swells and warms; silicon’s diffusivity depends steeply on temperature instead."],"refs":["plummer2000"],"example":{"xs":[15,30,60,120,240,480,960],"truth":{"k":0.06},"noise":0.03,"seed":3,"note":"Made with a slope of 0.06 mm²/min, an example value."}},{"id":"capacitor","n":4,"tier":0,"model":"capacitor","time":"45 minutes","title":"Build a capacitor from foil and paper","short":"The gate stack is a capacitor: thinner means stronger","question":"How does a capacitor depend on its area and on the thickness of the insulator between the plates?","analog":"The gate of every MOSFET is a capacitor: metal, a thin insulator, then silicon. This one is foil, paper, foil.","links":[{"label":"MOS capacitor lab","href":"physics.html#mos"},{"label":"Oxidation theatre","href":"fab.html#proc-oxidation"}],"need":["Two sheets of kitchen foil cut to the same size","Plain paper","A heavy book to press the stack flat","A multimeter with a capacitance range"],"steps":["Measure one paper sheet’s thickness: measure a stack of many sheets and divide.","Put one paper sheet between the two foils, press under the book and read the capacitance. Keep the leads still.","Repeat with two, three and four sheets, then with smaller foils.","Write one row per reading: foil overlap area in cm², paper thickness in µm and capacitance in pF."],"measure":"overlap area in cm², insulator thickness in µm, capacitance in pF","cols":[{"id":"area_cm2","label":"Area","unit":"cm²"},{"id":"t_um","label":"Thickness","unit":"µm"},{"id":"C_pF","label":"Capacitance","unit":"pF"}],"params":[],"results":[{"key":"eps_r","label":"Relative permittivity of the paper","unit":"","digits":2}],"compare":[{"text":"C = ε_r ε₀ A / t. Silicon dioxide has ε_r = 3.9, which is why high-k insulators replaced it once gate oxides grew too thin.","refs":["sze2006","robertson2006"]},{"text":"Real measurements stray: the 2024 cleanroom run’s oxide capacitors read up to about four times away from this ideal, because of the meter’s series resistance.","refs":["cleanroom_run_char2024"]}],"leaves_out":["Air gaps between foil and paper add a thin, low-permittivity layer in series.","Fringing fields at the edges add capacitance that the formula ignores."],"refs":["sze2006","robertson2006","cleanroom_run_char2024"],"example":{"xs":[1,2,3,4,6],"truth":{"A_cm2":100,"t_sheet_um":100,"eps_r":2.5},"noise":0.04,"seed":5,"note":"Made with 100 cm² of foil, 100 µm sheets and ε_r = 2.5, all example values."}},{"id":"cd","n":5,"tier":1,"model":"grating","time":"30 minutes","title":"Read a CD’s track pitch with a laser pointer","short":"Diffraction: the physics that limits lithography","question":"Can you measure a spacing of about a micrometre with a ruler and light?","analog":"A disc’s tracks are a diffraction grating, just like the lines on a photomask. A lens prints a pattern only if it catches the diffracted orders.","links":[{"label":"Lithography theatre","href":"fab.html#litho"},{"label":"Lithography optics lab","href":"physics.html#litho"},{"label":"Manual 4A: lithography","href":"manuals/lithography.html"}],"need":["A labelled Class 2 laser pointer with its wavelength printed on it","A CD or DVD","A wall or screen and a tape measure"],"steps":["Never look into the beam or point it at anyone. Keep reflections on the wall.","Shine the pointer through a clear spot on the disc, or reflect it straight back off the data side, onto a wall a metre or so away.","Measure the distance L from disc to wall.","Measure how far each bright spot sits from the central one: order m = 1, 2 and so on, on both sides.","Type L and the wavelength into the boxes, then one row per spot: the order m and its distance in millimetres."],"measure":"order m, spot distance from the centre in mm","cols":[{"id":"m","label":"Order m","unit":""},{"id":"x_mm","label":"Distance from centre","unit":"mm"}],"params":[{"id":"L_mm","label":"Disc to wall L","unit":"mm","value":1000},{"id":"lambda_nm","label":"Wavelength","unit":"nm","value":650}],"results":[{"key":"d_um","label":"Track pitch d","unit":"µm","digits":3}],"compare":[{"text":"The CD standard sets the track pitch at 1.6 µm.","refs":["ecma130"]},{"text":"The DVD standard sets it at 0.74 µm, so a red laser shows only the first order.","refs":["ecma267"]},{"text":"Class 2 is limited to 1 mW of visible light; never use an unlabelled or higher-class laser.","refs":["iec60825"]}],"leaves_out":["The grating equation d sin θ = m λ assumes the beam hits the disc square on.","A photomask is imaged by a lens, which collects only some orders; here the wall sees them all."],"refs":["ecma130","ecma267","iec60825","levinson2019"],"safety":"Use only a laser labelled Class 2 (or Class 1). Never look into the beam, and keep reflections away from eyes.","example":{"xs":[1,2,-1,-2],"truth":{"d_um":1.6,"lambda_nm":650,"L_mm":1000},"noise":0.01,"seed":7,"note":"Made with the CD pitch, 650 nm and L = 1 m; the wavelength and distance are example values."}},{"id":"diode","n":6,"tier":1,"model":"diode","time":"45 minutes","title":"Measure a diode’s current–voltage curve","short":"The p–n junction’s exponential law and its ideality factor","question":"How does the current through a silicon diode grow with voltage?","analog":"Every transistor contains p–n junctions. This is the same junction, in a glass package you can hold.","links":[{"label":"p–n junction lab","href":"physics.html#pn"},{"label":"Diffusion theatre","href":"fab.html#proc-diffusion"}],"need":["A small silicon signal diode","Two AA cells in a holder","A potentiometer and a resistor of about a kilohm in series","Two multimeters (one for volts, one for milliamps)"],"steps":["Wire cells, potentiometer, resistor and diode in a loop, with the diode’s band towards the negative side.","Put one meter across the diode (volts) and the other in the loop (milliamps).","Turn the potentiometer in small steps and note both readings each time, from a few microamps up to a few milliamps.","Write one row per step: diode voltage in volts and current in milliamps. Note the room temperature."],"measure":"voltage in V, current in mA","cols":[{"id":"V","label":"Voltage","unit":"V"},{"id":"I_mA","label":"Current","unit":"mA"}],"params":[{"id":"T_K","label":"Temperature","unit":"K","value":295}],"results":[{"key":"n","label":"Ideality factor n","unit":"","digits":3},{"key":"Is_A","label":"Saturation current I_s","unit":"A","digits":2,"sci":true}],"compare":[{"text":"Shockley’s junction law is I = I_s [exp(V / n V_T) − 1] with V_T = kT/q. An ideal diffusion current gives n = 1; recombination in the depletion region pushes n towards 2.","refs":["shockley1949","sze2006"]},{"text":"The 2024 cleanroom run’s own p–n diode turned on at about 0.44 V.","refs":["cleanroom_run_char2024"]}],"leaves_out":["At high current the diode’s series resistance bends the line down.","The diode warms as current rises, which shifts the curve."],"refs":["shockley1949","sze2006","cleanroom_run_char2024","schroder2006"],"example":{"xs":[0.4,0.45,0.5,0.55,0.6,0.65,0.7],"truth":{"Is_A":3e-09,"n":1.9,"T_K":295},"noise":0.03,"seed":2,"note":"Made with I_s = 3 nA and n = 1.9, example values."}},{"id":"led","n":7,"tier":1,"model":"led","time":"45 minutes","title":"Estimate Planck’s constant from LED colours","short":"Band gap, photon energy and colour","question":"Why does a blue LED need more voltage than a red one?","analog":"An LED is a p–n junction in a direct-gap semiconductor. Each electron that crosses the gap gives one photon, so the gap sets the colour.","links":[{"label":"Band gaps lab","href":"physics.html#kp"},{"label":"Device Atlas","href":"devices.html#atlas"}],"need":["LEDs of four or more colours, with their peak wavelengths from the seller","The same circuit as the diode experiment","Two multimeters"],"steps":["Wire each LED in turn in the diode circuit.","Raise the voltage slowly until the current reaches the same small value for every LED. Note the voltage: that is its turn-on voltage.","Write one row per LED: peak wavelength in nanometres and turn-on voltage in volts."],"measure":"wavelength in nm, turn-on voltage in V","cols":[{"id":"lambda_nm","label":"Wavelength","unit":"nm"},{"id":"V_on","label":"Turn-on voltage","unit":"V"}],"params":[],"results":[{"key":"h_Js","label":"Planck’s constant estimate","unit":"J s","digits":3,"sci":true},{"key":"V0","label":"Intercept","unit":"V","digits":2}],"compare":[{"text":"The exact value is h = 6.62607015 × 10⁻³⁴ J s.","refs":["codata2018"]},{"text":"Band gaps of LED materials are tabulated for each alloy.","refs":["vurgaftman2001"]}],"leaves_out":["Turn-on depends on the current you choose and on the series resistance, so the intercept is not zero.","An LED’s photon energy is close to, but not exactly, its band gap."],"refs":["codata2018","vurgaftman2001"],"example":{"xs":[470,525,590,625,660],"truth":{"h_Js":6e-34,"V0":0.1},"noise":0.01,"seed":4,"note":"Made with h = 6.0 × 10⁻³⁴ J s and a 0.1 V offset, example values."}},{"id":"mosfet","n":8,"tier":1,"model":"mosfet","time":"45 minutes","title":"Find a MOSFET’s threshold voltage","short":"The square law and the threshold, measured","question":"At what gate voltage does a transistor turn on, and how fast does its current grow after that?","analog":"A small discrete n-channel MOSFET is the same device as one transistor on a chip, only much larger.","links":[{"label":"MOSFET lab","href":"physics.html#mosfet"},{"label":"Manual 9: device modules","href":"manuals/modules.html"}],"need":["A small n-channel enhancement MOSFET for logic-level use","A 5 V USB supply or a battery pack","A potentiometer and a resistor of a few hundred ohms","Two multimeters"],"steps":["Tie the gate to the drain. Then the transistor is always in saturation, so one sweep gives the square law.","Feed the drain through the resistor and the potentiometer, with the source to negative.","Step the potentiometer and note the gate voltage and drain current at each step.","Write one row per step: gate voltage in volts and drain current in milliamps."],"measure":"gate voltage in V, drain current in mA","cols":[{"id":"V_GS","label":"Gate voltage","unit":"V"},{"id":"I_D_mA","label":"Drain current","unit":"mA"}],"params":[{"id":"keep","label":"Fit points above this share of the top current","unit":"","value":0.1}],"results":[{"key":"Vt","label":"Threshold voltage V_t","unit":"V","digits":2},{"key":"K_mA_per_V2","label":"Gain factor K","unit":"mA/V²","digits":2}],"compare":[{"text":"In saturation a long-channel MOSFET follows I_D = K (V_GS − V_t)², so √I_D is a straight line that crosses zero at V_t.","refs":["sze2006","schroder2006"]},{"text":"The 2024 cleanroom run’s test transistors measured V_t from −3.0 to +7.5 V, most between −1.8 and 0 V.","refs":["cleanroom_run_char2024"]}],"leaves_out":["Below threshold the current is exponential, not zero; the fit uses only the upper points.","Power transistors heat up, and mobility falls as the gate field rises."],"refs":["sze2006","schroder2006","cleanroom_run_char2024"],"example":{"xs":[1.6,1.8,2.0,2.2,2.4,2.6,2.8],"truth":{"Vt":1.5,"K_mA_per_V2":40},"noise":0.03,"seed":8,"note":"Made with V_t = 1.5 V and K = 40 mA/V², example values."}},{"id":"pencil","n":9,"tier":0,"model":"tlm","time":"40 minutes","title":"Draw pencil resistors and separate the contacts","short":"The transfer length method used on every wafer","question":"When you measure a resistor, how much of the resistance is the contacts and how much is the film?","analog":"Fabs measure contact resistance with test structures of the same width and different lengths. A graphite strip on paper is the film.","links":[{"label":"Probe theatre","href":"fab.html#proc-probe"},{"label":"Manual 11: probe","href":"manuals/probe.html"}],"need":["A soft pencil (6B or softer)","Paper and a ruler","A multimeter on its resistance range","Two paper clips or crocodile clips"],"steps":["Draw one strip of even width, heavily shaded, about 15 cm long.","Clip the meter’s leads at a fixed start and at points further along.","Read the resistance at several lengths, keeping the clip pressure the same.","Type the strip width, then one row per reading: length in millimetres and resistance in ohms."],"measure":"length in mm, resistance in Ω","cols":[{"id":"L_mm","label":"Length","unit":"mm"},{"id":"R_ohm","label":"Resistance","unit":"Ω"}],"params":[{"id":"W_mm","label":"Strip width","unit":"mm","value":5}],"results":[{"key":"Rs_ohm_sq","label":"Sheet resistance R_s","unit":"Ω/sq","digits":3},{"key":"Rc_ohm","label":"Contact resistance R_c","unit":"Ω","digits":3},{"key":"LT_mm","label":"Transfer length L_T","unit":"mm","digits":2}],"compare":[{"text":"R = 2R_c + R_s L/W. The slope gives the film; the intercept at L = 0 gives both contacts.","refs":["berger1972","schroder2006"]},{"text":"The 2024 cleanroom run’s diffused n⁺ resistor: 57.1 Ω over 201 µm by 11 µm, about 3.1 Ω per square.","refs":["cleanroom_run_char2024"]}],"leaves_out":["The strip’s width and shading vary along its length.","The transfer length here assumes long contacts; real test structures are designed for that."],"refs":["berger1972","schroder2006","cleanroom_run_char2024"],"example":{"xs":[20,40,60,80,100,120],"truth":{"Rs_ohm_sq":9000,"Rc_ohm":20000,"W_mm":5},"noise":0.02,"seed":9,"note":"Made with 9 kΩ per square and 20 kΩ contacts, example values."}},{"id":"thermometer","n":10,"tier":1,"model":"diode_temp","time":"1 hour","title":"Turn a diode into a thermometer","short":"How chips sense their own temperature","question":"At a fixed current, how does a diode’s voltage change with temperature?","analog":"Chips sense hot spots with on-die diodes. The physics is the saturation current, which rises steeply with temperature.","links":[{"label":"Carriers and band gaps lab","href":"physics.html#bands"},{"label":"Self-heating lab","href":"physics.html#heat"}],"need":["The diode circuit from experiment 6","A cup of warm water and a kitchen thermometer","A small plastic bag to keep the diode dry"],"steps":["Set a small, fixed current and leave the potentiometer alone from now on.","Put the bagged diode in cool water beside the thermometer. Wait a minute and note temperature and voltage.","Add warm water in steps (never hotter than a comfortable bath) and note both again each time.","Write one row per reading: temperature in °C and diode voltage in volts."],"measure":"temperature in °C, voltage in V","cols":[{"id":"T_C","label":"Temperature","unit":"°C"},{"id":"V","label":"Diode voltage","unit":"V"}],"params":[],"results":[{"key":"dVdT_mV_per_K","label":"Slope dV/dT","unit":"mV/K","digits":2},{"key":"V_at_0C","label":"Voltage at 0 °C","unit":"V","digits":3}],"compare":[{"text":"Shockley’s law with I_s ∝ T³ exp(−E_g/kT) predicts dV/dT = −(E_g/q − V)/T − 3k/q at constant current. The page computes it for your voltage.","refs":["sze2006","shockley1949"]}],"leaves_out":["The supply current drifts a little as the resistor warms.","Water lags behind the diode, so wait for readings to settle."],"refs":["sze2006","shockley1949"],"safety":"Use warm tap water only. Keep mains-powered equipment away from the water.","example":{"xs":[10,18,26,34,42],"truth":{"V_at_0C":0.62,"dVdT":-0.0021},"noise":0.002,"seed":10,"note":"Made with 0.62 V at 0 °C and −2.1 mV/K, example values."}},{"id":"sunprint","n":11,"tier":1,"model":"proximity","time":"2 hours","title":"Print a pattern with sunlight","short":"Proximity printing, the first lithography","question":"How small a line can a mask print when it does not touch the paper?","analog":"Sun-print paper is a photoresist that water develops. Early chip makers printed masks in contact or close proximity, just like this.","links":[{"label":"Lithography theatre","href":"fab.html#litho"},{"label":"Manual 4B: photomask","href":"manuals/photomask.html"}],"need":["Sun-print paper sold for children’s crafts","A transparency sheet printed with sets of lines of falling width","Thin card or paper spacers","A tray of water"],"steps":["Lay a mask straight on the paper (no gap) and others on stacks of spacers of known thickness.","Expose in sunshine for the time on the packet, then rinse in water.","Find the narrowest line set that still printed as separate lines for each gap.","Write one row per gap: gap in µm and smallest resolved width in µm."],"measure":"gap in µm, smallest resolved line width in µm","cols":[{"id":"gap_um","label":"Gap","unit":"µm"},{"id":"w_um","label":"Smallest line","unit":"µm"}],"params":[],"results":[{"key":"lambda_eff_nm","label":"Effective wavelength","unit":"nm","digits":0}],"compare":[{"text":"In proximity printing the smallest feature grows as √(λg): diffraction spreads the light across the gap g.","refs":["plummer2000","levinson2019"]}],"leaves_out":["Sunlight is not a point source, so its angle adds blur in proportion to the gap.","Paper is rough, so “resolved” is a judgement."],"refs":["plummer2000","levinson2019"],"example":{"xs":[100,200,400,800,1600],"truth":{"lambda_um":0.9},"noise":0.05,"seed":12,"note":"Made with an effective wavelength of 900 nm, an example value that includes blur from the sun’s angle."}},{"id":"crystal","n":12,"tier":1,"model":"crystal","time":"1 to 2 weeks","title":"Grow a crystal from a seed","short":"Seeded growth, the idea behind Czochralski","question":"If a seed crystal sits in a saturated solution, how steadily does it grow?","analog":"A silicon ingot grows from a small seed that sets the orientation of the whole crystal. Table salt grows from a seed in the same way, much more slowly.","links":[{"label":"Czochralski theatre","href":"fab.html#proc-czochralski"},{"label":"Manual 1: wafer","href":"manuals/wafer.html"}],"need":["Table salt and warm water (an adult pours)","A clean jar and a thread","A kitchen scale reading to 0.1 g"],"steps":["Dissolve salt in warm water until no more will dissolve. Let it cool and pour off the clear liquid.","Tie a small, clear seed crystal to the thread and hang it in the liquid.","Each day lift it out, dry it gently, weigh it and hang it back.","Write one row per day: day number and mass in grams."],"measure":"day, mass in g","cols":[{"id":"day","label":"Day","unit":""},{"id":"mass_g","label":"Mass","unit":"g"}],"params":[],"results":[{"key":"rate_g_per_day","label":"Growth rate","unit":"g/day","digits":3}],"compare":[{"text":"A Czochralski puller sets growth by pull rate and temperature gradient, so the ingot grows at a steady, chosen speed.","refs":["plummer2000"]}],"leaves_out":["Growth here is set by evaporation and room temperature, which drift.","Extra crystals grow on the thread and the jar and steal salt from the seed."],"refs":["plummer2000"],"example":{"xs":[1,2,3,4,5,6,7,8],"truth":{"m0":0.2,"rate":0.15},"noise":0.03,"seed":6,"note":"Made with 0.15 g/day from 0.2 g, example values."}},{"id":"fourpoint","n":13,"tier":2,"model":"fourpoint","time":"1 lab session","title":"Measure a wafer with a four-point probe","short":"Sheet resistance without the contacts","question":"How do you measure a film’s resistance when every contact adds resistance of its own?","analog":"Four needles in a line: current through the outer two, voltage across the inner two. The voltage needles carry no current, so their contacts drop no voltage.","links":[{"label":"Probe theatre","href":"fab.html#proc-probe"},{"label":"A real cleanroom run","href":"process.html#labrun"}],"need":["A four-point probe station in a supervised teaching lab","A wafer or a doped test region"],"steps":["Follow the lab’s own procedure and supervision for the probe station.","Measure the voltage at several currents, in both directions.","Write one row per reading: current in milliamps and voltage in millivolts."],"measure":"current in mA, voltage in mV","cols":[{"id":"I_mA","label":"Current","unit":"mA"},{"id":"V_mV","label":"Voltage","unit":"mV"}],"params":[],"results":[{"key":"Rs_ohm_sq","label":"Sheet resistance R_s","unit":"Ω/sq","digits":3}],"compare":[{"text":"For a thin, wide sheet R_s = (π / ln 2)·V/I ≈ 4.532 V/I.","refs":["smits1958","schroder2006"]},{"text":"The 2024 cleanroom run measured its substrate at 8.74 Ω per square.","refs":["cleanroom_run_fab2024","teaching_char_manual2024"]}],"leaves_out":["The factor π/ln 2 assumes a sheet much wider than the probe spacing and much thinner than it; small samples need correction factors.","Heating at high current changes the reading."],"refs":["smits1958","schroder2006","cleanroom_run_fab2024","teaching_char_manual2024"],"safety":"A teaching-lab instrument: use it only under that lab’s supervision and rules.","example":{"xs":[0.5,1,2,3,4,-1,-2],"truth":{"Rs_ohm_sq":8.74},"noise":0.01,"seed":13,"note":"Made with the run’s 8.74 Ω per square."}},{"id":"etch","n":14,"tier":3,"model":"etch","time":"institution only","title":"Read an etch rate from a test series","short":"Etch rate and selectivity, conceptually","question":"How do engineers turn a few timed test etches into a rate they can trust?","analog":"Before etching real wafers, a lab etches test pieces for different times, measures what was removed and fits a line.","links":[{"label":"Etch theatre","href":"fab.html#proc-etch"},{"label":"Manual 5: etch","href":"manuals/etch.html"}],"need":["Only in an institution’s cleanroom, under its training and rules. No chemistry is described here."],"steps":["Trained staff etch test pieces for a series of times and measure the film removed.","Plot removed thickness against time. The slope is the etch rate; the intercept on the time axis is the delay before etching starts.","Repeat for the mask material: the ratio of the two rates is the selectivity."],"measure":"time in s, thickness removed in nm","cols":[{"id":"t_s","label":"Time","unit":"s"},{"id":"removed_nm","label":"Removed","unit":"nm"}],"params":[],"results":[{"key":"rate_nm_per_min","label":"Etch rate","unit":"nm/min","digits":1},{"key":"delay_s","label":"Start delay","unit":"s","digits":1}],"compare":[{"text":"A straight line with a short delay is what a steady, reaction-limited etch looks like.","refs":["plummer2000","coburn1989"]}],"leaves_out":["Rates change with pattern density and loading, so a blanket test piece is only a start.","No chemistry, concentration or temperature is given: those belong to the institution’s own procedure."],"refs":["plummer2000","coburn1989"],"safety":"Institution only. Hazardous chemistry is never done at home; this page explains the method, not a recipe.","example":{"xs":[30,60,90,120,180],"truth":{"rate_nm_per_s":1.0,"delay_s":5},"noise":0.02,"seed":14,"note":"Made with 1 nm/s and a 5 s delay, example values."}}]};
